/* Excel-compatible UTF-8 CSV exchange. Preview first; commit the whole batch once. */
const exchangeMasters=['customers','bikes','parts','staff','services','accounts','insurance','appointments','expenses'];
const exchangeImports=[...exchangeMasters,'godown','purchases'];
function csvCell(value){let text=String(value??'');if(typeof value==='string'&&/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}
function exchangeDownload(rows,name){download('\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'BIKE-DOCTOR-'+name+'-'+today()+'.csv','text/csv;charset=utf-8')}
function exchangeFields(key){if(key==='godown')return ['reference','part','qty','unitCost','date','note'];if(key==='purchases')return ['id','supplier','invoice','date','part','qty','price','gst','stockLocation','advance','mode','account','invoiceType','notes'];return schemas[key].filter(f=>f.key).map(f=>f.key)}
function exchangeTemplate(key){let fields=exchangeFields(key),sample=exchangeExample(key);return [fields,fields.map(field=>sample[field]??'')]}
function exchangeExample(key){
 let sample={};for(let f of schemas[key]||[]){if(!f.key)continue;let options=typeof f.options==='function'?f.options():f.options||[],first=options[0];sample[f.key]=f.default??(f.type==='select'?(typeof first==='object'?first.value:first)||'':f.type==='number'?0:'')}
 let marker='EXAMPLE-REPLACE-ME',date=today(),account=db.accounts[0]?.id||'',part=db.parts[0]?.id||'REPLACE-WITH-SAVED-SKU',vehicle=db.bikes[0]?.id||'REPLACE-WITH-VEHICLE-ID',customer=db.customers[0]?.id||'REPLACE-WITH-CUSTOMER-ID';
 const examples={customers:{id:marker,name:'Example Customer',mobile:'9000000000',address:'Example address',city:'Example City',state:'Uttar Pradesh'},bikes:{id:marker,customer,number:'DEMO-XX-0000',brand:list('Vehicle Brands')[0]||'Honda',model:'Example Model',year:2026},parts:{id:marker,name:'Example Spare Part',category:list('Spare Part Categories')[0]||'Engine',brand:'Example Brand',vehicleMake:list('Vehicle Brands')[0]||'Honda',vehicleModel:'Example Model',unit:'PCS',rack:'A-01',purchase:100,purchaseDate:date,price:150,gst:18,opening:10,min:2,notes:'Example only — replace or delete this row'},staff:{id:marker,name:'Example Mechanic',mobile:'9000000000',designation:list('Staff Designations')[0]||'Mechanic',salaryType:'Per Job',salary:30,joining:date,experience:2},services:{id:marker,name:'Example Service',charge:500,status:'Active',description:'Example only — replace or delete this row'},accounts:{id:marker,name:'Example Cash Account',type:'Cash in Hand',opening:0,status:'Active'},insurance:{id:marker,bike:vehicle,issue:date,expiry:new Date(Date.parse(date+'T00:00:00Z')+365*86400000).toISOString().slice(0,10),provider:'Example Insurer',policy:'EXAMPLE-POLICY',premium:1000},appointments:{id:marker,date,name:'Example Customer',mobile:'9000000000',number:'DEMO-XX-0000',brand:list('Vehicle Brands')[0]||'Honda',model:'Example Model',complaint:'General service',notes:'Example only — replace or delete this row'},expenses:{id:marker,date,amount:100,mode:'Cash',account,description:'Example expense — replace or delete this row'},godown:{reference:marker,part,qty:10,unitCost:100,date,note:'Example only — replace or delete this row'},purchases:{id:marker,supplier:'Example Vendor',invoice:'EXAMPLE-BILL-001',date,part,qty:2,price:100,gst:18,stockLocation:'main',advance:0,mode:'Cash',account,invoiceType:'gst',notes:'Example only — replace or delete this row'}};
 return {...sample,...examples[key]};
}
function exchangeDate(value,label,optional=false){if(!value&&optional)return '';let text=String(value||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(text)||!Number.isFinite(Date.parse(text))||new Date(text+'T00:00:00Z').toISOString().slice(0,10)!==text)throw Error(label+': use a valid YYYY-MM-DD date');return text}
function exchangeNumber(value,label,positive=false){if(String(value??'').trim()===''||!Number.isFinite(Number(value))||Number(value)<0||positive&&Number(value)<=0)throw Error(label+': enter a '+(positive?'positive':'non-negative')+' number');return Number(value)}
function exchangePart(value){let exact=find('parts',value);if(exact)return exact.id;let rows=db.parts.filter(p=>p.name.toLowerCase()===String(value||'').trim().toLowerCase());if(rows.length===1)return rows[0].id;throw Error('Unknown or ambiguous spare part: '+value+'. Use its saved SKU.')}
function exchangeRows(key,text){
 let rows=parseCsv(text);if(rows.length<2)throw Error('Include column headers and at least one data row.');if(rows.length>1001)throw Error('Maximum 1,000 rows per import. Split the file into smaller batches.');
 let normalize=v=>String(v).toLowerCase().replace(/[^a-z0-9]/g,''),fields=exchangeFields(key),aliases={partcodesku:key==='parts'?'id':'part',sku:key==='parts'?'id':'part',partcode:key==='parts'?'id':'part',partname:key==='parts'?'name':'part',customername:'name',staffname:'name',servicename:'name',vehiclenumber:'number',mobilenumber:'mobile',emailid:'email',purchaseprice:key==='parts'?'purchase':'price',purchasecostperunit:key==='godown'?'unitCost':'price',sellingprice:'price',purchasedate:key==='parts'?'purchaseDate':'date',quantity:'qty',openingstock:key==='godown'?'qty':'opening',suppliername:'supplier',vendor:'supplier',supplierinvoicebillno:'invoice',purchaseid:'id',receivedinto:'stockLocation',paidamount:'advance',entryreference:'reference',vehiclemake:'vehicleMake',vehiclemodel:key==='parts'?'vehicleModel':'model',rackno:'rack',minstockalert:'min',customerid:key==='bikes'?'customer':'id',vehicleid:key==='insurance'?'bike':'id',staffid:'id',serviceid:'id'};
 let headers=rows.shift().map(h=>{let normalized=normalize(h),direct=fields.find(f=>normalize(f)===normalized);return direct||aliases[normalized]||schemas[key]?.find(f=>f.key&&normalize(f.label)===normalized)?.key||''});
 if(headers.some(h=>!fields.includes(h)))throw Error('Unrecognized column. Download this module’s template and keep its headers.');if(new Set(headers).size!==headers.length)throw Error('Duplicate column headers.');
 return rows.map((row,i)=>{if(row.length>headers.length)throw Error('Row '+(i+2)+': too many cells');let record={};headers.forEach((h,n)=>record[h]=String(row[n]??'').trim());return record});
}
function prepareMasterExchange(key,rows){let ids=new Set();return rows.map((input,index)=>{let record={};for(let f of schemas[key].filter(f=>f.key)){let value=input[f.key]??f.default??'';if(f.required&&f.key!=='id'&&!String(value).trim())throw Error('Row '+(index+2)+': missing '+f.label);if(f.type==='number')value=exchangeNumber(value===''?0:value,f.label);if(f.type==='date')value=exchangeDate(value,f.label,!f.required);if(f.required&&f.key!=='id'&&!String(value).trim())throw Error('Row '+(index+2)+': missing '+f.label);if(f.type==='select'&&value!==''){let options=typeof f.options==='function'?f.options():f.options||[];if(options.length&&!options.some(o=>String(typeof o==='object'?o.value:o)===String(value)))throw Error('Row '+(index+2)+': invalid '+f.label)}record[f.key]=value}
 if(record.id){if(find(key,record.id)||ids.has(record.id))throw Error('Existing or duplicate ID: '+record.id);ids.add(record.id)}
 for(let [fieldName,target]of key==='bikes'?[['customer','customers']]:key==='insurance'?[['bike','bikes']]:key==='expenses'?[['account','accounts'],['staff','staff']]:[])if(record[fieldName]&&!find(target,record[fieldName]))throw Error('Unknown '+fieldName+' ID: '+record[fieldName]);
 if(key==='parts'&&!['0','5','12','18','28'].includes(String(record.gst)))throw Error('Invalid part GST percentage');if(key==='expenses'&&Number(record.amount)<=0)throw Error('Expense amount must be greater than zero');
 if(key==='bikes'&&(db.bikes.some(b=>b.number.toLowerCase()===record.number.toLowerCase())||rows.slice(0,index).some(b=>String(b.number).toLowerCase()===record.number.toLowerCase())))throw Error('Vehicle number already exists: '+record.number);
 return record})}
function prepareGodownExchange(rows){let references=new Set();return rows.map(row=>{if(!row.reference)throw Error('Every opening row needs a unique reference.');if(references.has(row.reference)||(db.stockMovements||[]).some(m=>m.importReference===row.reference))throw Error('Opening reference already imported: '+row.reference);references.add(row.reference);return {...validateStockMovement({kind:'opening',part:exchangePart(row.part),qty:exchangeNumber(row.qty,'Quantity',true),unitCost:exchangeNumber(row.unitCost,'Purchase cost'),date:exchangeDate(row.date,'Purchase date'),note:row.note}),importReference:row.reference}})}
function preparePurchaseExchange(rows){let groups=new Map(),identities=new Set();for(let row of rows){if(!row.supplier||!row.invoice)throw Error('Supplier and supplier invoice number are required.');let identity=vendorKey(row.supplier)+'|'+row.invoice.toLowerCase(),groupKey=row.id||identity;let metadata={id:row.id||'',supplier:row.supplier,invoice:row.invoice,date:exchangeDate(row.date,'Purchase date'),stockLocation:(row.stockLocation||'main').toLowerCase(),advance:exchangeNumber(row.advance||0,'Paid amount'),mode:row.mode||'Cash',account:row.account||'',invoiceType:row.invoiceType||'gst',notes:row.notes||'',discount:0,tax:0};if(!['main','godown'].includes(metadata.stockLocation)||!['gst','non-gst'].includes(metadata.invoiceType))throw Error('Use main/godown for stockLocation and gst/non-gst for invoiceType.');if(metadata.account&&!find('accounts',metadata.account))throw Error('Unknown payment account: '+metadata.account);if(metadata.advance&&!metadata.account)throw Error('A payment account ID is required for a paid purchase.');
 if(!groups.has(groupKey)){if(row.id&&find('purchases',row.id)||identities.has(identity)||db.purchases.some(b=>vendorKey(b.supplier)+'|'+String(b.invoice||'').toLowerCase()===identity))throw Error('Purchase ID or supplier invoice already exists.');identities.add(identity);groups.set(groupKey,{...metadata,partLines:[]})}let bill=groups.get(groupKey);for(let key of Object.keys(metadata))if(bill[key]!==metadata[key])throw Error('Repeated invoice rows must have the same supplier, date, paid amount, account and stock destination.');let gst=exchangeNumber(row.gst||0,'GST');if(![0,5,12,18,28].includes(gst))throw Error('Invalid purchase GST percentage');bill.partLines.push({part:exchangePart(row.part),qty:exchangeNumber(row.qty,'Quantity',true),price:exchangeNumber(row.price,'Purchase cost'),gst:metadata.invoiceType==='non-gst'?0:gst})}
 for(let bill of groups.values())if(bill.advance>billTotals(bill).total)throw Error('Paid amount cannot exceed purchase invoice total.');return [...groups.values()]}
function prepareExchange(key,text){if(!exchangeImports.includes(key))throw Error('Import is not available for this module.');let rows=exchangeRows(key,text);if(rows.some(row=>row.id==='EXAMPLE-REPLACE-ME'||row.reference==='EXAMPLE-REPLACE-ME'))throw Error('Replace or delete the example row, including its EXAMPLE-REPLACE-ME ID/reference, before importing.');return key==='godown'?prepareGodownExchange(rows):key==='purchases'?preparePurchaseExchange(rows):prepareMasterExchange(key,rows)}
function commitExchange(key,prepared){let before=structuredClone(db);try{if(key==='godown'){db.stockMovements=db.stockMovements||[];for(let record of prepared){if((db.stockMovements||[]).some(m=>m.importReference===record.importReference))throw Error('This opening reference is already imported.');validateStockMovement(record);let n=1;while(db.stockMovements.some(m=>m.id==='MOV-'+String(n).padStart(5,'0')))n++;db.stockMovements.push({...record,id:'MOV-'+String(n).padStart(5,'0'),createdAt:new Date().toISOString()})}}else for(let record of prepared){if(record.id&&find(key,record.id))throw Error('Record ID now exists. Preview the file again.');db[key].push({...record,id:record.id||nextId(key)})}audit('Import',prepared.length+' '+key+' records imported from Excel-compatible CSV');if(save('Import completed')===false){db=before;return false}return true}catch(error){db=before;throw error}}
openCsvImport=function(key){if(!exchangeImports.includes(key))return toast('This module supports export only.');let plan=[];openModal('Import Excel-compatible CSV — '+(titles[key]||key),'<div class="formbody"><p>In Excel, use Save As → CSV UTF-8. Download the template with its example row. Replace or delete that row, including the EXAMPLE-REPLACE-ME ID/reference, then select your CSV below. Dates: DD/MM/YYYY. Keep phone numbers and IDs as text. Maximum 1,000 rows / 5 MB.</p><p>'+esc(key==='godown'?'Opening stock only, using existing part SKUs. Give each row a unique reference; reimporting the same reference is blocked. This does not create supplier purchases.':key==='purchases'?'One row per part. Repeat the same purchase ID, supplier invoice, date, paid amount and account on every row of the invoice. Paid amount is counted once per invoice. Use saved part/account IDs.':'Creates new records only. Existing IDs are never overwritten. Linked customers, vehicles and accounts must already exist.')+'</p><button type="button" class="btn secondary" id="exchangeTemplate">Download Template</button><label class="field"><span>CSV File</span><input type="file" id="csvImportFile" accept=".csv,text/csv"></label><div id="csvImportPreview" role="status"></div></div><div class="formactions">'+btn('Cancel','cancel','secondary')+'<button type="button" class="btn" id="confirmCsvImport" disabled>Import Records</button></div>');$('#exchangeTemplate').onclick=()=>exchangeDownload(exchangeTemplate(key),key+'-import-template');$('#csvImportFile').onchange=async e=>{plan=[];$('#confirmCsvImport').disabled=true;try{let file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('File must be under 5 MB');let text=await file.text();plan=prepareExchange(key,text);$('#csvImportPreview').innerHTML='<p>Ready: '+plan.length+' '+(key==='purchases'?'purchase invoices':'records')+'. Review the first 10 below before importing.</p>'+table(['ID / Reference','Name / Vendor / Part','Date','Quantity / Item Lines'],plan.slice(0,10).map(r=>[esc(r.id||r.importReference||'Auto ID'),esc(r.name||r.supplier||r.number||r.part||r.description||''),esc(r.date||r.purchaseDate||''),r.qty??r.partLines?.length??'—']));$('#confirmCsvImport').disabled=false;$('#confirmCsvImport').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{let fresh=prepareExchange(key,text);if(key==='accounts'?await window.importCloudAccounts(fresh):key==='expenses'?await window.importCloudExpenses(fresh):commitExchange(key,fresh)){closeModal();render();if(['accounts','expenses'].includes(key))toast('Records imported to Cloudflare D1.')}}catch(error){toast(error.message)}finally{button.disabled=false}}}catch(error){$('#csvImportPreview').textContent='Import rejected: '+error.message;plan=[];$('#confirmCsvImport').disabled=true}}};
function exportGodownInventory(){let headers=['Part Code / SKU','Part Name','HSN','Category','Brand','Vehicle Make','Vehicle Model','Unit','Rack','Purchase Price','Selling Price','GST (%)','Minimum Stock','Godown Opening Stock','Godown Stock','Main Stock','Latest Godown Purchase Date','Latest Godown Purchase Cost','Linked Vendors'];exchangeDownload([headers,...db.parts.filter(p=>matches({...p,vendors:partVendorNames(p.id)})).map(p=>{let receipt=godownPurchaseDetails(p.id);return [p.id,p.name,p.hsn||'',p.category||'',p.brand||'',p.vehicleMake||'',p.vehicleModel||'',p.unit||'PCS',p.rack||'',p.purchase,p.price,p.gst??0,p.min??0,godownOpeningStock(p.id),godownStock(p.id),stock(p.id),receipt?.date||'',receipt?.cost??'',partVendorNames(p.id)]})],'godown-inventory')}
function exportGodownMovementHistory(){let headers=['Movement ID','Date','Part Name','Part Code / SKU','From','To','Quantity','Purchase Cost / Unit','GST (%)','Price incl. GST / Unit','Selling Price / Unit','Purchase Date','Reference / Notes'],records=(db.stockMovements||[]).slice().reverse().filter(m=>matches({...m,name:name('parts',m.part)})).map(m=>[m.id,m.date,name('parts',m.part),m.part,m.kind==='opening'?'Opening Balance':'Godown',m.kind==='opening'?'Godown':'Main Stock',m.qty,m.unitCost==null?'':m.unitCost,m.purchaseGstRate??'',m.unitCostAfterGst??'',m.sourceSellingPrice??find('parts',m.part)?.price??'',m.purchaseDate||'',m.note||'']);exchangeDownload([headers,...records],'godown-movement-history')}
const exportBeforeExchange=exportTable;
exportTable=function(){if(exchangeMasters.includes(page)){let fields=exchangeFields(page),records=db[page].filter(r=>matches(page==='parts'?{...r,vendors:partVendorNames(r.id)}:r)).filter(r=>!filter||(page==='parts'?stockStatus(r)===filter:[r.status,r.category,r.type].includes(filter)));exchangeDownload([page==='parts'?[...fields,'currentStock','linkedVendors']:fields,...records.map(r=>page==='parts'?[...fields.map(key=>r[key]??''),stock(r.id),partVendorNames(r.id)]:fields.map(key=>r[key]??''))],page);return}return exportBeforeExchange()};
const renderBeforeExchange=render;
render=function(){renderBeforeExchange();let toolbar=$('#content .toolbar');if(toolbar&&exchangeImports.includes(page)&&!toolbar.querySelector('[data-importcsv]'))toolbar.insertAdjacentHTML('beforeend','<button type="button" class="btn success" data-importcsv="'+esc(page)+'">'+icon('file')+' Import Excel</button>');if(page==='godown'){if(toolbar&&!$('#exportGodownInventory'))toolbar.insertAdjacentHTML('beforeend','<button type="button" class="btn exportButton" id="exportGodownInventory">'+icon('download')+' Export Excel</button>');if($('#exportGodownInventory'))$('#exportGodownInventory').onclick=exportGodownInventory;if($('#exportGodownHistory'))$('#exportGodownHistory').onclick=exportGodownMovementHistory}};
render();
